import java.lang.reflect.*;

class VulnerableApp {
    private String secret;

    public VulnerableApp(String secret) {
        this.secret = secret;
    }

    // This is a private method - using reflection to access it is vulnerable
    public String getSecretViaReflection() {
        try {
            return SecretAccessor.getSecret(this);
        } catch (Exception e) {
            throw new RuntimeException("Failed to get secret", e);
        }
    }
}

class SecretAccessor {
    private static String getSecret(Object obj) {
        // This is a private method - reflection bypasses access control
        return obj.getClass().getDeclaredMethod("getSecret").invoke(obj);
    }
}

public class Main {
    public static void main(String[] args) {
        VulnerableApp app = new VulnerableApp("secret123");
        String secret = app.getSecretViaReflection();
        System.out.println("Secret retrieved: " + secret);
    }
}
