# Good code - using proper Java API with security best practices
import java.lang.reflect.*;
import java.security.*;

class SecureApp {
    private String secret;

    public SecureApp(String secret) {
        this.secret = secret;
    }

    // Using proper API methods instead of reflection
    public String getSecret() {
        return secret;
    }

    // For more complex scenarios, use secure reflection with proper checks
    public String getSecretViaReflection() {
        try {
            // Only reflect on public classes and methods
            Class<?> clazz = Class.forName("SecureApp");
            Method[] methods = clazz.getDeclaredMethods();

            for (Method m : methods) {
                if (m.getName().equals("getSecret")) {
                    return (String) m.invoke(this);
                }
            }
            throw new RuntimeException("getSecret method not found");
        } catch (Exception e) {
            throw new RuntimeException("Reflection failed", e);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        SecureApp app = new SecureApp("secret123");
        String secret = app.getSecret();
        System.out.println("Secret retrieved: " + secret);
    }
}
